import{_ as t,o as r,c as s,a3 as i}from"./chunks/framework.I6s8z2kk.js";const p=JSON.parse('{"title":"Managing services","description":"","frontmatter":{},"headers":[],"relativePath":"user/center/services.md","filePath":"user/center/services.md"}'),n={name:"user/center/services.md"};function o(a,e,d,g,c,l){return r(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="managing-services" tabindex="-1">Managing services <a class="header-anchor" href="#managing-services" aria-label="Permalink to &quot;Managing services&quot;">​</a></h1><p>A <strong>service</strong> is something you sell. There are eight types, and each has its own permission.</p><table tabindex="0"><thead><tr><th>Type</th><th>What it is</th><th>How clients buy it</th></tr></thead><tbody><tr><td><strong>Recreational riding</strong></td><td>Guided rides</td><td>Pick a day and an hour</td></tr><tr><td><strong>Visit</strong></td><td>Entry to the center</td><td>Pick a day (or a set time)</td></tr><tr><td><strong>Event</strong></td><td>A dated event</td><td>Buy tickets</td></tr><tr><td><strong>Resort</strong></td><td>Overnight stays</td><td>Pick a date range, add optional extras</td></tr><tr><td><strong>Horse care</strong></td><td>Care offers for a horse</td><td>Price options</td></tr><tr><td><strong>Horse service</strong></td><td>Other horse services</td><td>Price options</td></tr><tr><td><strong>Training</strong></td><td>Lessons with a trainer</td><td>Pick an hour with a trainer</td></tr><tr><td><strong>Membership</strong></td><td>A membership with included visits</td><td>Buy a membership</td></tr></tbody></table><h2 id="creating-and-editing" tabindex="-1">Creating and editing <a class="header-anchor" href="#creating-and-editing" aria-label="Permalink to &quot;Creating and editing&quot;">​</a></h2><p>Open the type from <strong>Services</strong>, then <strong>New</strong>. Names and descriptions are written in <strong>English and Arabic</strong>. New services start <strong>Active</strong>.</p><ul><li>The <strong>type</strong>, <strong>center</strong> and <strong>link (slug)</strong> of a service never change after creation.</li><li>Add <strong>photos</strong>: a cover and gallery images.</li><li>Turn <strong>settings</strong> on or off per service, for example <em>single-session booking</em>, <em>package booking</em> and <em>cash on arrival</em>.</li></ul><h2 id="prices" tabindex="-1">Prices <a class="header-anchor" href="#prices" aria-label="Permalink to &quot;Prices&quot;">​</a></h2><p>Each service has <strong>price options</strong> (for example 30, 60 or 90 minutes, each with a price). Prices are in SAR.</p><ul><li>Editing a price option keeps packages that were already sold. Removing an option removes its package from sale.</li><li><strong>Packages</strong> let clients pay once for several sessions. Each price option can have one package.</li><li>The <strong>lowest price</strong> is shown to clients as the starting price (&quot;from&quot;). For resorts, extras are not counted.</li><li>While one of your <a href="./promotions">promotions</a> is running, clients also see the <strong>discounted price</strong>.</li></ul><h2 id="trainers" tabindex="-1">Trainers <a class="header-anchor" href="#trainers" aria-label="Permalink to &quot;Trainers&quot;">​</a></h2><p>Add <strong>trainers</strong> with their own weekly schedule and capacity per hour. A training service is linked to one or more trainers.</p><h2 id="hiding-or-removing" tabindex="-1">Hiding or removing <a class="header-anchor" href="#hiding-or-removing" aria-label="Permalink to &quot;Hiding or removing&quot;">​</a></h2><p>Set a service <strong>Inactive</strong> to hide it from clients without losing it. <strong>Deleting</strong> removes it from sale; past bookings and reports keep their history.</p><p>Clients only ever see <strong>active</strong> services of a <strong>visible, active</strong> center.</p>',14)])])}const m=t(n,[["render",o]]);export{p as __pageData,m as default};
